Solution A: function generateFPSMap(canvasId) {
    const TILE_SIZE = 10;
    const MAP_TILES = 50; // 500 / 10
    const MIN_ROOM_SIZE = 6;
    const MAX_ROOM_SIZE = 15;
    const MAX_SPLIT_ITER = 5;
    const SPAWN_COUNT = 2;
    const WEAPON_COUNT = 5;
    const colors        floor: "#777777",
        wall: "#000000",
        spawn: "#00ff00",
        weapon: "#ff0000"
    };
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    canvas.width = canvas.height = MAP_TILES * TILE_SIZE;
    // clear previous UI
    let container = canvas.parentNode;
    let legend = container.querySelector(".fps-legend");
    let button = container.querySelector(".fps-generate");
    if (!legend) {
        legend = document.createElement("div");
        legend.className = "fps-legend";
        legend.style.marginTop = "8px";
        legend.style.fontFamily = "sans-serif";
        legend.style.fontSize = "12px";
        const items = [
            {color: colors.wall, text: "Wall"},
            {color: colors.floor, text: "Floor"},
            {color: colors.spawn, text: "Spawn"},
            {color: colors.weapon, text: "Weapon"}
        ];
        items.forEach(it => {
            const box = document.createElement("span");
            box.style.display = "inline-block";
            box.style.width = "12px";
            box.style.height = "12px";
            box.style.background = it.color;
            box.style.marginRight = "4px";
            box.style.verticalAlign = "middle";
            const label = document.createElement("span");
            label.textContent = it.text;
            label.style.marginRight = "12px";
            legend.appendChild(box);
            legend.appendChild(label);
        });
        container.appendChild(legend);
 }
    if (!button) {
        button = document.createElement("button");
        button.className = "fps-generate";
        button.textContent = "Generate New Map";
        button.style.display = "block";
        button.style.marginTop = "8px";
        button.addEventListener("click", () => generateFPSMap(canvasId));
        container.appendChild(button);
    }
    // map data: 0 floor,1 wall,2 spawn,3 weapon
    const map = new Uint8Array(MAP_TILES * MAP_TILES);
    function index(x, y) { return y * MAP_TILES + x; }
    // fill walls
    for (let i = 0; i < map.length; i++) map[i] = 1;
    // BSP rooms
    const rooms = [];
    function splitRegion(x, y, w, h, depth) {
        if (depth >= MAX_SPLIT_ITER ||
            (w <= MAX_ROOM_SIZE && h <= MAX_ROOM_SIZE)) {
            const rw = Math.max(MIN_ROOM_SIZE, Math.min(w - 2, Math.floor(Math.random() * (MAX_ROOM_SIZE - MIN_ROOM_SIZE)) + MIN_ROOM_SIZE));
            const rh = Math.max(MIN_ROOM_SIZE, Math.min(h - 2, Math.floor(Math.random() * (MAX_ROOM_SIZE - MIN_ROOM_SIZE)) + MIN_ROOM_SIZE));
            const rx = x + Math.floor((w - rw) / 2);
            const ry = y + Math.floor((h - rh) / 2);
            rooms.push({x: rx, y: ry, w: rw, h: rh, cx: rx + Math.floor(rw/2), cy: ry + Math.floor(rh/2)});
            return;
        }
        const horizontal = w > h;
        if (horizontal) {
            const split = Math.floor(Math.random() * (w - MIN_ROOM_SIZE * 2)) + MIN_ROOM_SIZE;
            splitRegion(x, y, split, h, depth + 1);
            splitRegion(x + split, y, w - split, h, depth + 1);
        } else {
            const split = Math.floor(Math.random() * (h - MIN_ROOM_SIZE * 2)) + MIN_ROOM_SIZE;
            splitRegion(x, y, w, split, depth + 1);
            splitRegion(x, y + split, w, h - split, depth + 1);
        }
    }
    splitRegion(1, 1, MAP_TILES - 2, MAP_TILES - 2, 0);
    // carve rooms
    rooms.forEach(r => {
        for (let yy = r.y; yy < r.y + r.h; yy++) {
            for (let xx = r.x; xx < r.x + r.w; xx++) {
                map[index(xx, yy)] = 0;
            }
        }
    });
    // corridors (connect rooms linearly)
    rooms.sort((a, b) => a.cx - b.cx);
    for (let i = 0; i < rooms.length - 1; i++) {
        const a = rooms[i];
        const b = rooms[i + 1];
        if (Math.random() < 0.5) {
            carveH(a.cx, b.cx, a.cy);
            carveV(a.cy, b.cy, b.cx);
        } else {
            carveV(a.cy, b.cy, a.cx);
            carveH(a.cx, b.cx, b.cy);
        }
    }
    function carveH(x1, x2, y) {
        const start = Math.min(x1, x2), end = Math.max(x1, x2);
        for (let x = start; x <= end; x++) {
            map[index(x, y)] = 0;
        }
    }
    function carveV(y1, y2, x) {
        const start = Math.min(y1, y2), end = Math.max(y1, y2);
        for (let y = start; y <= end; y++) {
            map[index(x, y)] = 0;
        }
    }
    // place spawns farthest apart
    function dist(a, b) {
        const dx = a.cx - b.cx, dy = a.cy - b.cy;
        return dx * dx + dy * dy;
    }
    let maxD = -1, pair = null;
    for (let i = 0; i < rooms.length; i++) {
        for (let j = i + 1; j < rooms.length; j++) {
            const d = dist(rooms[i], rooms[j]);
            if (d > maxD) { maxD = d; pair = [rooms[i], rooms[j]]; }
        }
    }
    if (pair) {
        map[index(pair[0].cx, pair[0].cy)] = 2;
        map[index(pair[1].cx, pair[1].cy)] = 2;
    }
    // place weapons
    const weaponRooms = rooms.filter(r => map[index(r.cx, r.cy)] === 0);
    for (let i = 0; i < WEAPON_COUNT && weaponRooms.length; i++) {
        const idx = Math.floor(Math.random() * weaponRooms.length);
        const r = weaponRooms.splice(idx, 1)[0];
        map[index(r.cx, r.cy)] = 3;
    }
    // flood fill check
    function floodFrom(x, y) {
        const visited = new Uint8Array(MAP_TILES * MAP_TILES);
        const stack = [x, y];
        while (stack.length) {
            const cy = stack.pop();
            const cx = stack.pop();
            const i = index(cx, cy);
            if (visited[i] || map[i] === 1) continue;
            visited[i] = 1;
            if (cx > 0) stack.push(cx - 1, cy);
            if (cx < MAP_TILES - 1) stack.push(cx + 1, cy);
            if (cy > 0) stack.push(cx, cy - 1);
            if (cy < MAP_TILES - 1) stack.push(cx, cy + 1);
        }
        return visited;
    }
    // find first spawn
    let spawnPos = null;
    for (let y = 0; y < MAP_TILES; y++) {
        for (let x = 0; x < MAP_TILES; x++) {
            if (map[index(x, y)] === 2) { spawnPos = {x, y}; break; }
        }
        if (spawnPos) break;
    }
    if (spawnPos) {
        const visited = floodFrom(spawnPos.x, spawnPos.y);
        // if any floor not visited, regenerate
        let allReachable = true;
        for (let i = 0; i < map.length; i++) {
            if (map[i] !== 1 && !visited[i]) { allReachable = false; break; }
        }
        if (!allReachable) {
            // simple retry
            setTimeout(() => generateFPSMap(canvasId), 0);
            return;
        }
    }
    // draw map
    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        for (let y = 0; y < MAP_TILES; y++) {
            for (let x = 0; x < MAP_TILES; x++) {
                const v = map[index(x, y)];
                let col;
                if (v === 1) col = colors.wall;
                else if (v === 0) col = colors.floor;
                else if (v === 2) col = colors.spawn;
                else if (v === 3) col = colors.weapon;
                ctx.fillStyle = col;
                ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            }
        }
    }
    requestAnimationFrame(draw);
}

Solution B: ```javascript
function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const size = 500;
    const tiles = 50;
    const tileSize = size / tiles;
    const MAX_ROOMS = 10;
    const ROOM_MIN = 6;
    const ROOM_MAX = 10;
    const WEAPON_COUNT = 6;
    const SPAWN_COUNT = 4;

    const COLORS = {
        wall: '#000000',
        floor: '#404040',
        spawn: '#00FF00',
        weapon: '#FF0000'
    };

    // Utility functions
    function rand(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
    function dist(a, b) { return Math.abs(a.x - b.x) + Math.abs(a.y - b.y); }

    // Create map array
    function createGrid() {
        const grid = new Array(tiles);
        for (let i = 0; i < tiles; i++) {
            grid[i] = new Array(tiles).fill(1); // wall
        }
        return grid;
    }

    // Room object
    class Room {
        constructor(x, y, w, h) {
            this.x = x;
            this.y = y;
            this.w = w;
            this.h = h;
            this.center = {x: Math.floor(x + w / 2), y: Math.floor(y + h / 2)};
        }
        intersect(r) {
            return !(this.x + this.w < r.x || r.x + r.w < this.x ||
                     this.y + this.h < r.y || r.y + r.h < this.y);
        }
    }

    // Generate rooms
    function generateRooms() {
        const rooms = [];
        let attempts = 0;
        while (rooms.length < MAX_ROOMS && attempts < 200) {
            const w = rand(ROOM_MIN, ROOM_MAX);
            const h = rand(ROOM_MIN, ROOM_MAX);
            const x = rand(1, tiles - w - 1);
            const y = rand(1, tiles - h - 1);
            const newRoom = new Room(x, y, w, h);
            let ok = true;
            for (let r of rooms) {
                if (newRoom.intersect(r)) { ok = false; break; }
            }
            if (ok) rooms.push(newRoom);
            attempts++;
        }
        return rooms;
    }

    // Carve rooms into grid
    function carveRooms(grid, rooms) {
        for (let r of rooms) {
            for (let i = r.x; i < r.x + r.w; i++) {
                for (let j = r.y; j < r.y + r.h; j++) {
                    grid[i][j] = 0; // floor
                }
            }
        }
    }

    // Connect rooms with corridors
    function connectRooms(grid, rooms) {
        for (let i = 1; i < rooms.length; i++) {
            const c1 = rooms[i - 1].center;
            const c2 = rooms[i].center;
            if (Math.random() < 0.5) {
                horizontalCorridor(grid, c1.x, c2.x, c1.y);
                verticalCorridor(grid, c1.y, c2.y, c2.x);
            } else {
                verticalCorridor(grid, c1.y, c2.y, c1.x);
                horizontalCorridor(grid, c1.x, c2.x, c2.y);
            }
        }
    }

    function horizontalCorridor(grid, x1, x2, y) {
        for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) grid[x][y] = 0;
    }

    function verticalCorridor(grid, y1, y2, x) {
        for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) grid[x][y] = 0;
    }

    // Flood-fill reachability
    function floodFill(grid, start) {
        const visited = new Array(tiles).fill(0).map(()=>Array(tiles).fill(false));
        const stack = [start];
        while (stack.length) {
            const {x, y} = stack.pop();
            if (x < 0 || x >= tiles || y < 0 || y >= tiles) continue;
            if (visited[x][y] || grid[x][y] !== 0) continue;
            visited[x][y] = true;
            stack.push({x:x+1, y});
            stack.push({x:x-1, y});
            stack.push({x, y:y+1});
            stack.push({x, y:y-1});
        }
        return visited;
    }

    // Place spawn points
    function placeSpawns(grid, rooms) {
        const spawns = [];
        const corners = [
            {x: 1, y: 1},
            {x: tiles-2, y: 1},
            {x: 1, y: tiles-2},
            {x: tiles-2, y: tiles-2}
        ];
        for (let i = 0; i < SPAWN_COUNT; i++) {
            const c = corners[i];
            if (grid[c.x][c.y] === 0) {
                grid[c.x][c.y] = 2; // spawn
                spawns.push(c);
            } else {
                // find nearest floor near corner
                for (let d = 1; d < tiles; d++) {
                    const dirs = [
                        {x: c.x + d, y: c.y},
                        {x: c.x - d, y: c.y},
                        {x: c.x, y: c.y + d},
                        {x: c.x, y: c.y - d}
                    ];
                    for (let p of dirs) {
                        if (p.x >=0 && p.x<tiles && p.y>=0 && p.y<tiles && grid[p.x][p.y]===0) {
                            grid[p.x][p.y]=2;
                            spawns.push(p);
                            break;
                        }
                    }
                    if (spawns.length>i) break;
                }
            }
        }
        return spawns;
    }

    // Place weapons
    function placeWeapons(grid, spawns) {
        const weapons = [];
        let attempts = 0;
        while (weapons.length < WEAPON_COUNT && attempts < 1000) {
            const x = rand(1, tiles-2);
            const y = rand(1, tiles-2);
            if (grid[x][y] !== 0) { attempts++; continue; }
            if (spawns.some(s=>dist(s, {x,y})<5)) { attempts++; continue; }
            grid[x][y] = 3; // weapon
            weapons.push({x,y});
        }
    }

    // Draw map
    function draw(grid) {
        ctx.clearRect(0,0,size,size);
        for (let i=0;i<tiles;i++) {
            for (let j=0;j<tiles;j++) {
                const type=grid[i][j];
                if (type===1) ctx.fillStyle=COLORS.wall;
                else if (type===0) ctx.fillStyle=COLORS.floor;
                else if (type===2) ctx.fillStyle=COLORS.spawn;
                else if (type===3) ctx.fillStyle=COLORS.weapon;
                ctx.fillRect(i*tileSize, j*tileSize, tileSize, tileSize);
            }
        }
    }

    // Legend
    function createLegend() {
        let legend = document.getElementById('legend');
        if (!legend) {
            legend = document.createElement('div');
            legend.id = 'legend';
            legend.style.position = 'absolute';
            legend.style.top = '10px';
            legend.style.left = '10px';
            legend.style.padding = '5px';
            legend.style.backgroundColor = 'rgba(0,0,0,0.5)';
            legend.style.color = '#fff';
            legend.style.fontSize = '12px';
            legend.style.lineHeight = '18px';
            document.body.appendChild(legend);
        }
        legend.innerHTML = `
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.wall}"></span> Wall</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.floor}"></span> Floor</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.spawn}"></span> Spawn</div>
            <div><span style="display:inline-block;width:12px;height:12px;background:${COLORS.weapon}"></span> Weapon</div>
        `;
    }

    // Generate button
    function createButton() {
        let btn = document.getElementById('generateBtn');
        if (!btn) {
            btn = document.createElement('button');
            btn.id = 'generateBtn';
            btn.textContent = 'Generate New Map';
            btn.style.position = 'absolute';
            btn.style.bottom = '10px';
            btn.style.left = '10px';
            btn.style.padding = '5px 10px';
            document.body.appendChild(btn);
            btn.addEventListener('click', () => generateFPSMap(canvasId));
        }
    }

    // Main generation loop
    while (true) {
        const grid = createGrid();
        const rooms = generateRooms();
        carveRooms(grid, rooms);
        connectRooms(grid, rooms);
        const spawns = placeSpawns(grid, rooms);
        placeWeapons(grid, spawns);
        const reachable = floodFill(grid, spawns[0] || {x:1,y:1});
        // Count reachable floor tiles
        let reachableFloor = 0, totalFloor = 0;
        for (let i=0;i<tiles;i++)for(let j=0;j<tiles;j++){
            if(grid[i][j]===0||grid[i][j]===2||grid[i][j]===3){ totalFloor++; if(reachable[i][j]) reachableFloor++; }
        }
        if(reachableFloor===totalFloor) {
            draw(grid);
            createLegend();
            createButton();
            break;
        }
    }
}
